// Writes the Go tables that are copied, not computed, from the pinned packages:
// ../../ziggurat.go (numpy's ziggurat constants, from cursory-js) and
// ../../bigrams.go (myuri's English bigram table). Re-run it, and gen.mjs, when
// either version in package.json changes.
//
//   npm ci && node tables.mjs
import { writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const modules = join(here, 'node_modules');
// File paths, not package specifiers: neither package exports these files.
const zig = createRequire(import.meta.url)(join(modules, 'cursory-js/dist/random/ziggurat.js'));
const bigrams = await import(pathToFileURL(join(modules, '@jwriter20/myuri/dist/typing/bigrams.js')));

const repr = (v) => { const s = String(v); return /[.eE]/.test(s) ? s : `${s}.0`; };
const table = (name, values, hex) => {
    let out = `var ${name} = [256]${hex ? 'uint64' : 'float64'}{\n`;
    for (let i = 0; i < values.length; i += 4) {
        out += `\t${values.slice(i, i + 4).map((v) => (hex ? `0x${v.toString(16).padStart(16, '0')}` : repr(v))).join(', ')},\n`;
    }
    return `${out}}\n\n`;
};

const ziggurat = `// Code generated by testdata/gen/tables.mjs from cursory-js 2.1.0 dist/random/ziggurat.js (numpy ziggurat_constants.h); DO NOT EDIT.

package myuri

const (
	zigguratNorR    = ${repr(zig.ZIGGURAT_NOR_R)}
	zigguratNorInvR = ${repr(zig.ZIGGURAT_NOR_INV_R)}
)

${table('kiDouble', zig.KI_DOUBLE, true)}${table('wiDouble', zig.WI_DOUBLE, false)}${table('fiDouble', zig.FI_DOUBLE, false)}`;
writeFileSync(join(here, '..', '..', 'ziggurat.go'), ziggurat.trimEnd() + '\n');

const bigramGo = `// Code generated by testdata/gen/tables.mjs from @jwriter20/myuri 4.0.0 dist/typing/bigrams.js; DO NOT EDIT.

package myuri

// bigramTableB64 is 676 bytes, a-z x a-z: byte = round(-20 * log10(share of all bigrams)).
// English bigram counts from John Burkardt's NGRAMS dataset (GNU LGPL), see NOTICE.
const bigramTableB64 = "${bigrams.BIGRAM_TABLE_B64}"

// bigramMeanLog10 is the frequency-weighted mean log10 share.
const bigramMeanLog10 = ${repr(bigrams.BIGRAM_MEAN_LOG10)}
`;
writeFileSync(join(here, '..', '..', 'bigrams.go'), bigramGo);
